int Find_Sign_PBH(double x)
{
    // Find sign of a number
    int result;
    if (x > 0.0)
    {
        result = 1;
    }
    else if (x < 0.0)
    {
        result = -1;
    }
    else
    {
        // maybe x is too close to 0?
        result = 0;
    }
    return result;
}

int Find_Index_1D_PBH(double *Tab, double x, int nx)
{
    // Find closest left element index
    // return -1 if not in range
    double x1, x2, x3;
    int id1, id2, id3, Stop, s1, s2, s3, idx, count;
    Stop = 0;
    id1 = 0;
    id3 = nx - 1;

    count = 0;
    while (Stop == 0)
    {
        count = count + 1;
        id2 = (int)round((((double)id1) + ((double)id3)) / 2.0);
        if (id3 == id1 + 1)
        {
            idx = id1;
            // printf("Stopping, id1 = %d, id2 = %d, id3 = %d\n", id1, id2, id3);
            Stop = 1;
        }

        x1 = Tab[id1];
        x2 = Tab[id2];
        x3 = Tab[id3];

        s1 = Find_Sign_PBH(x - x1);
        s2 = Find_Sign_PBH(x - x2);
        s3 = Find_Sign_PBH(x - x3);
        if (s1 != s2)
        {
            id3 = id2;
        }
        else if (s2 != s3)
        {
            id1 = id2;
        }
        if ((s1 == s3) || (count > 50))
        {
            idx = -1;
            Stop = 1;
        }
    }
    return idx;
}

double Read_Tab_2D_PBH(int yid, int xid, int ny, int nx, double *Tab)
{
    // A way to read 2D table, I can't get pointer to work
    int id;
    if ((xid > nx - 1) || (yid > ny - 1))
    {
        printf("Error: array index overflow.\n");
        exit(1);
    }
    id = yid * nx + xid;
    return Tab[id];
}

double Interp_2D_PBH(double m, double z, double *m_axis, double *z_axis, double *Tab, int nm, int nz, int Overflow_Handle)
{
    /* Interpolate (in log) from a 2D table
     -- inputs --
     m : m target
     z : z target
     m_axis : m axis pointer
     z_axis : z axis pointer
     Tab : Data Table, index : Tab[z_id][m_id]
     nm : m axis size
     nz : z axis size
     Overflow_Handle : decide what to do when m or z is not in range
                       0 : Raise error and exit
                       1 : return 0 when z is not in range, if m is also not in range then raise error
    */
    int mid1, mid2, zid1, zid2;
    double lm, lm1, lm2, lz, lz1, lz2, f11, f12, f21, f22, f1, f2, F1, F2, f;
    mid1 = Find_Index_1D_PBH(m_axis, m, nm);
    zid1 = Find_Index_1D_PBH(z_axis, z, nz);
    // printf("debug: m = %E,  z = %E\n", m, z);

    if ((mid1 == -1) || (zid1 == -1))
    {
        // Overflow detected
        if (Overflow_Handle == 0)
        {
            printf("Error: m or z not in range, exitting, debugging info:.\n");
            printf("m1 = %E, m = %E, m2 = %E\n", m_axis[mid1], m, m_axis[mid1 + 1]);
            printf("z1 = %E, z = %E, z2 = %E\n", z_axis[zid1], z, z_axis[zid1 + 1]);
            printf("min(m) = %E, m = %E, max(m) = %E\n", m_axis[0], m, m_axis[nm - 1]);
            printf("min(z) = %E, z = %E, max(z) = %E\n", z_axis[0], z, z_axis[nz - 1]);
            exit(1);
        }
        else if ((zid1 == -1) && (Overflow_Handle == 1))
        {
            if (mid1 == -1)
            {
                printf("Error: m not in range, exitting, debugging info:.\n");
                printf("m1 = %E, m = %E, m2 = %E\n", m_axis[mid1], m, m_axis[mid1 + 1]);
                printf("z1 = %E, z = %E, z2 = %E\n", z_axis[zid1], z, z_axis[zid1 + 1]);
                printf("min(m) = %E, m = %E, max(m) = %E\n", m_axis[0], m, m_axis[nm - 1]);
                printf("min(z) = %E, z = %E, max(z) = %E\n", z_axis[0], z, z_axis[nz - 1]);
                exit(1);
            }
            else
            {
                // Our z axis is bounded
                return 0.0;
            }
        }
    }

    mid2 = mid1 + 1;
    zid2 = zid1 + 1;

    lm = log10(m);
    lm1 = log10(m_axis[mid1]);
    lm2 = log10(m_axis[mid2]);

    lz = log10(z);
    lz1 = log10(z_axis[zid1]);
    lz2 = log10(z_axis[zid2]);

    f11 = Read_Tab_2D_PBH(zid1, mid1, nz, nm, Tab);
    f12 = Read_Tab_2D_PBH(zid1, mid2, nz, nm, Tab);
    f21 = Read_Tab_2D_PBH(zid2, mid1, nz, nm, Tab);
    f22 = Read_Tab_2D_PBH(zid2, mid2, nz, nm, Tab);

    // fix m1
    f1 = f11;
    f2 = f21;
    F1 = (f2 - f1) / (lz2 - lz1) * (lz - lz1) + f1;
    // fix m2
    f1 = f12;
    f2 = f22;
    F2 = (f2 - f1) / (lz2 - lz1) * (lz - lz1) + f1;

    f = (F2 - F1) / (lm2 - lm1) * (lm - lm1) + F1;

    return f;
}

int Convert_to_Int(double x)
{
    int ix;
    ix = (int)round(x);
    return ix;
}

double Interp_EFF_Hawking(double Mbh, double z, int Dep_Channel)
{
    /* Interpolate PBH Hawking Radiation deposition efficiencies
    inputs:
    Mbh : PBH mass in gram
    z : redshift
    PBH_Spin : PBH_Spin
    PBH_Model : PBH_Model defined in energy_injection.h
    Dep_Channel: Deposition Channel
            1 - HIon
            3 - LyA
            4 - Heat
    */
    double EFF, Tbh;
    Tbh = 1.06E6 * (1.0E16 / Mbh); // BH temperature in eV
    if (Dep_Channel == 1)
    {
        EFF = Interp_2D_PBH(Tbh, 1 + z, Kerr_PBH_Temperature_Axis, Redshift_Axis, EFF_Hawking_HIon_K1, Kerr_PBH_Temperature_Size, Redshift_Size_PBH, 1);
    }
    else if (Dep_Channel == 3)
    {
        EFF = Interp_2D_PBH(Tbh, 1 + z, Kerr_PBH_Temperature_Axis, Redshift_Axis, EFF_Hawking_LyA_K1, Kerr_PBH_Temperature_Size, Redshift_Size_PBH, 1);
    }
    else if (Dep_Channel == 4)
    {
        EFF = Interp_2D_PBH(Tbh, 1 + z, Kerr_PBH_Temperature_Axis, Redshift_Axis, EFF_Hawking_Heat_K1, Kerr_PBH_Temperature_Size, Redshift_Size_PBH, 1);
    }
    else
    {
        fprintf(stderr, "Error: Wrong choice of Dep_Channel!\n");
        exit(EXIT_FAILURE);
    }
    return EFF;
}

// ALL dEdVdt are in ev/cm^3/s unit

double dEdVdt_Hawking_inj(double z, double Mbh, double fbh, double odmh2)
{
    // Hawking Radiation injection, Normalised to mbh>10^17 g
    // See Eq (3.10) of arxiv 2108.13256
    double r;
    r = 5.626976744186047e+29 / pow(Mbh, 3.0) * fbh * odmh2 * pow(1. + z, 3.0);
    return r;
}

double dEdVdt_Hawking_Mono_dep(double z, double Mbh, double fbh, double odmh2, int dep_channel)
{
    // Hawking Radiation monochromatic deposition rate
    double inj, r, EFF, Mdm;
    inj = dEdVdt_Hawking_inj(z, Mbh, fbh, odmh2);
    EFF = Interp_EFF_Hawking(Mbh, z, dep_channel);
    r = EFF * inj;
    return r;
}

